const touchSCIMToken = `-- name: TouchSCIMToken :exec
INSERT INTO scim_tokens (name, last_used_at) VALUES ($1, now())
ON CONFLICT (name) DO UPDATE SET last_used_at = now()
`

func (q *Queries) TouchSCIMToken(ctx context.Context, name string) error {
	_, err := q.db.Exec(ctx, touchSCIMToken, name)
	return err
}

const unbindSCIMUser = `-- name: UnbindSCIMUser :exec
UPDATE users SET scim_id = NULL, updated_at = now() WHERE scim_id = $1
`

// A SCIM DELETE: the row stays, deactivated, and keeps its name and external ID.
func (q *Queries) UnbindSCIMUser(ctx context.Context, scimID pgtype.UUID) error {
	_, err := q.db.Exec(ctx, unbindSCIMUser, scimID)
	return err
}

const updateSCIMGroup = `-- name: UpdateSCIMGroup :one
UPDATE scim_groups SET external_id = $2, display_name = $3, updated_at = now() WHERE id = $1 RETURNING id, org_id, external_id, display_name, created_at, updated_at
`

type UpdateSCIMGroupParams struct {
	ID          uuid.UUID
	ExternalID  string
	DisplayName string
}

func (q *Queries) UpdateSCIMGroup(ctx context.Context, arg UpdateSCIMGroupParams) (ScimGroup, error) {
	row := q.db.QueryRow(ctx, updateSCIMGroup, arg.ID, arg.ExternalID, arg.DisplayName)
	var i ScimGroup
	err := row.Scan(
		&i.ID,
		&i.OrgID,
		&i.ExternalID,
		&i.DisplayName,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

